          {#if selected.kind==='catalog_object'}<div class="inspector-section"><h3>Produktvariante</h3><p class="field-hint">{selected.productVariantVersionId.startsWith('unassigned')?'Freies Hüllmodell · kein bestellbarer Artikel':(products.find((p:any)=>(p.version_id??p.product_variant_version_id??p.id)===selected.productVariantVersionId)?.name??'Eingefrorener Herstellerartikel')}</p><p class="inspector-info">2D-Darstellung: {selected.accuracy==='verified_original'?'verifizierte Originalkontur':selected.accuracy==='verified_envelope'?'verifizierte Nennmaßhülle':'vereinfachte Hülle'}. Ein reales Produkt wird durch Variantenwahl geändert.</p><label class="inspector-label" for="catalog-version">Verfügbare Variante</label><ProductPicker id="catalog-version" initial={products} allowEmpty={false} value={selected.productVariantVersionId.startsWith('unassigned')?'':selected.productVariantVersionId} onchange={value=>replaceCatalog(value)}/><label class="inspector-label" for="catalog-original">Geprüfte Originalversion</label><ReferencePicker id="catalog-original" reference="product-model-assets" parentId={selected.productVariantVersionId.startsWith('unassigned')?'':selected.productVariantVersionId} initial={(data.related?.assets??[]).filter((a:any)=>a.product_variant_version_id===(selected?.kind==='catalog_object'?selected.productVariantVersionId:null)&&a.geometry_verified&&['mesh','outline'].includes(a.kind)&&hasAssetUsage(a,'internal_consultation')).map((a:any)=>({id:a.id,name:a.name??(a.kind==='mesh'?'Originales 3D-Modell':'Originale 2D-Kontur')}))} value={selected.assetVersionId??''} onchange={value=>{if(selected?.kind==='catalog_object')replaceCatalog(selected.productVariantVersionId,value||null);}}/><p class="field-hint">Die 2D-Hülle und ein verifiziertes 3D-Original werden getrennt ausgewiesen. Modelle werden mit belegten Einheiten und Achsen geladen; Größenänderungen erfordern eine andere Produktvariante.</p><a class="text-button" href="/product-assets">Produktdateien und Nutzungsnachweise verwalten</a><div class="inspector-actions"><button class="btn small" onclick={()=>addKind='connection'}>Anschluss</button><button class="btn small" onclick={()=>addKind='clearance'}>Freizone</button></div></div>{/if}
          {#if selected.kind==='surface'}<div class="inspector-section"><h3>Belagsfläche</h3><p class="field-hint">{{floor:'Boden',wall:'Wand',ceiling:'Decke',shower:'Dusche',inscription:'Beschriftungsfl\u00e4che'}[selected.surfaceType]} · {selected.layers.length} Schichten</p><MeasurementField snapshot={activeSnapshot!} measureId={selected.jointWidthMeasureId} label="Fugenbreite" onchange={edit} actorId={data.user?.id??''} canConfirm={canRelease} disabled={!canEdit||isHistoric}/><label class="inspector-label">Verlegerichtung (Grad)<input value={selected.layingDirectionDeg??''} onchange={(event)=>edit([{type:'set_surface_spec',elementId:selected!.id,layingDirectionDeg:event.currentTarget.value?event.currentTarget.value.replace(',','.'):null}])}/></label></div>{/if}
          {#if selected.kind==='wall'}<WallGeometryEditor snapshot={activeSnapshot!} wall={selected} onchange={edit} disabled={!canEdit||isHistoric}/>{/if}{#if ['wall','surface','room'].includes(selected.kind)}<LayerEditor snapshot={activeSnapshot!} element={selected} materials={materials} products={products} documents={data.related?.documents??[]} actorId={data.user?.id??''} canConfirm={canRelease} disabled={!canEdit||isHistoric} onchange={edit}/>{/if}
          {#if selected.kind==='machining'}<div class="inspector-section"><MachiningEditor snapshot={activeSnapshot!} feature={selected} assets={data.related?.assets??[]} documents={data.related?.documents??[]} onchange={edit} actorId={data.user?.id??''} canConfirm={canRelease} disabled={!canEdit||isHistoric}/></div>{/if}
          {#if selected.kind==='room'}<RoomBoundaryEditor snapshot={activeSnapshot!} room={selected} onchange={edit} disabled={!canEdit||isHistoric}/><div class="inspector-section"><h3>Raum & Höhenbezug</h3><label class="inspector-label">Bestehender Raum<select value={selected.roomId} onchange={(event)=>edit([{type:'set_room_spec',elementId:selected!.id,roomId:event.currentTarget.value}])}><option value={selected.roomId}>Aktueller Bezug</option>{#each data.lookups?.rooms??[] as room}<option value={room.id}>{room.name}</option>{/each}</select></label><label class="inspector-label">Geschoss<select value={selected.floorId} onchange={(event)=>edit([{type:'set_room_spec',elementId:selected!.id,floorId:event.currentTarget.value}])}><option value={selected.floorId}>Aktueller Bezug</option>{#each data.lookups?.floors??[] as floor}<option value={floor.id}>{floor.name}</option>{/each}</select></label><MeasurementField snapshot={activeSnapshot!} measureId={selected.finishedFloorLevelMeasureId} label="Oberkante Fertigfußboden" elementId={selected.id} field="finishedFloorLevelMeasureId" onchange={edit} actorId={data.user?.id??''} canConfirm={canRelease} evidence={data.related?.documents??[]} disabled={!canEdit||isHistoric}/></div>{/if}
          {#if selected.kind==='technical_note'}<div class="inspector-section"><h3>Ausführungshinweis</h3><label class="inspector-label">Wörtlicher Hinweis<textarea rows="5" value={selected.text} onchange={(event)=>{if(selected?.kind==='technical_note')edit([{type:'set_technical_note',elementId:selected.id,text:event.currentTarget.value,category:selected.category,ruleVersionId:selected.ruleVersionId}]);}}></textarea></label><label class="inspector-label">Prüfart<select value={selected.category} onchange={(event)=>{if(selected?.kind==='technical_note')edit([{type:'set_technical_note',elementId:selected.id,text:selected.text,category:event.currentTarget.value as any,ruleVersionId:selected.ruleVersionId}]);}}><option value="information">Information</option><option value="approval_required">Fachfreigabe erforderlich</option><option value="installation">Montagehinweis</option><option value="source">Quelle</option></select></label></div>{/if}
          {#if selected.kind==='grave_border'||selected.kind==='slope'||selected.kind==='connection'||selected.kind==='clearance'}<div class="inspector-section"><h3>Fachmaße</h3>{#each (selected.kind==='grave_border'?[['widthMeasureId','Randbreite'],['heightMeasureId','Randhöhe']]:selected.kind==='slope'?[['riseMeasureId','Höhenunterschied'],['runMeasureId','Lauflänge']]:selected.kind==='connection'?[['diameterMeasureId','Anschlussdurchmesser']]:[['heightMeasureId','Freizuhaltende Höhe']]) as [field,label]}<MeasurementField snapshot={activeSnapshot!} measureId={(selected as any)[field]} {label} elementId={selected.id} {field} onchange={edit} actorId={data.user?.id??''} canConfirm={canRelease} evidence={data.related?.documents??[]} disabled={!canEdit||isHistoric}/>{/each}{#if selected.kind==='connection'}<label class="inspector-label">Anschlussart<select value={selected.connectionType} onchange={(event)=>{if(selected?.kind==='connection')edit([{type:'set_connection_spec',elementId:selected.id,connectionType:event.currentTarget.value as any,specificationVersionId:selected.specificationVersionId,hostElementId:selected.hostElementId}]);}}><option value="water">Wasser</option><option value="waste">Abfluss</option><option value="electric">Elektro</option><option value="fastening">Befestigung</option><option value="joint">Fuge</option><option value="other">Andere</option></select></label>{/if}</div>{/if}
          {#if !['group','node','dimension','plan_reference','machining','inscription'].includes(selected.kind)}<TechnicalReferencesEditor snapshot={activeSnapshot!} element={selected} documents={data.related?.documents??[]} materials={materials} finishes={finishes} rules={data.related?.rules??[]} actorId={data.user?.id??''} canConfirm={canRelease} onchange={edit}/>{/if}
