  .studio-root{--studio-ink:var(--ink);--studio-green:var(--forest);--studio-muted:var(--muted);--studio-border:var(--line);color:var(--studio-ink)}.studio-heading{padding:2px 0 21px}.studio-breadcrumb{display:flex;gap:10px;font-size:12px;color:var(--muted);margin-bottom:17px}.studio-breadcrumb a{color:var(--muted)}.studio-title-row{display:flex;justify-content:space-between;align-items:flex-start;flex-wrap:wrap;gap:20px}.studio-title-row>div:first-child{flex:1 1 280px;min-width:0}.studio-title-row h1{line-height:1.2;margin:0 0 9px;font-size:28px;letter-spacing:-.035em;font-weight:600;}.studio-title-row p{color:var(--muted);display:flex;align-items:center;gap:7px;margin:0;font-size:12px;}.sync-dot{width:6px;height:6px;background:#527c60;border-radius:50%}.sync-dot.unsaved{background:#b58c3e}.sync-dot.has-conflict{background:#b84935}.revision-chip{background:var(--wash);color:var(--muted);border-radius:3px;padding:3px 6px;margin-left:6px}.heading-actions{display:flex;flex:0 1 auto;max-width:100%;gap:8px;align-items:center;justify-content:flex-end;flex-wrap:wrap}.heading-actions .btn{flex:0 0 auto;min-width:max-content;white-space:nowrap;overflow-wrap:normal;word-break:normal}.studio-notice{display:flex;gap:10px;align-items:flex-start;padding:12px 15px;border:1px solid var(--line);margin-bottom:13px;font-size:12px;line-height:1.6;background:var(--wash);border-radius:10px;}.studio-notice span{flex:1;white-space:pre-wrap}.studio-notice button{border:0;background:none;color:inherit;font-size:20px;cursor:pointer}.studio-notice.danger,.conflict-panel{background:var(--danger-wash);border-color:var(--line);color:var(--danger)}.studio-notice.warning{background:var(--warning-wash);border-color:var(--line);color:var(--warning)}.conflict-panel{padding:18px;border:1px solid var(--line);margin-bottom:16px}.conflict-panel h3{margin:0 0 8px}.conflict-panel p{font-size:13px;line-height:1.6}.conflict-panel>div{display:flex;gap:8px;flex-wrap:wrap}.variant-bar{display:flex;align-items:c